// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title DistributedCacheRelay
 * @notice Manages distributed cache node authentication and message relay
 * @dev Uses challenge-response authentication similar to NTLM for node verification
 */
contract DistributedCacheRelay is Ownable {
    using ECDSA for bytes32;

    enum AuthState { IDLE, CHALLENGE_SENT, AUTHENTICATED }

    struct NodeSession {
        address nodeAddress;
        bytes32 challenge;
        uint256 challengeTimestamp;
        AuthState state;
        uint256 nonce;
        bool relayEnabled;
    }

    struct CacheEntry {
        bytes32 key;
        bytes value;
        uint256 timestamp;
        address origin;
    }

    mapping(address => NodeSession) public sessions;
    mapping(bytes32 => CacheEntry) public cache;
    mapping(address => bool) public trustedRelays;

    uint256 public constant CHALLENGE_TIMEOUT = 300; // 5 minutes
    uint256 public constant MAX_RELAY_DEPTH = 3;

    bytes32 private _domainSeparator;
    address private _configOracle;
    bool private _allowRelayForwarding;

    event ChallengeIssued(address indexed node, bytes32 challenge);
    event NodeAuthenticated(address indexed node);
    event CacheUpdated(bytes32 indexed key, address indexed origin);
    event RelayForwarded(address indexed from, address indexed to, bytes32 key);

    constructor(address configOracle_) {
        _configOracle = configOracle_;
        _domainSeparator = keccak256(abi.encode(
            keccak256("EIP712Domain(string name,uint256 chainId,address verifyingContract)"),
            keccak256("DistributedCacheRelay"),
            block.chainid,
            address(this)
        ));
        _allowRelayForwarding = true;
    }

    function initiateAuth(address node) external returns (bytes32) {
        require(sessions[node].state == AuthState.IDLE, "Session active");

        bytes32 challenge = keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            node,
            sessions[node].nonce
        ));

        sessions[node] = NodeSession({
            nodeAddress: node,
            challenge: challenge,
            challengeTimestamp: block.timestamp,
            state: AuthState.CHALLENGE_SENT,
            nonce: sessions[node].nonce + 1,
            relayEnabled: false
        });

        emit ChallengeIssued(node, challenge);
        return challenge;
    }

    function respondToChallenge(bytes memory signature) external {
        NodeSession storage session = sessions[msg.sender];
        require(session.state == AuthState.CHALLENGE_SENT, "No pending challenge");
        require(
            block.timestamp - session.challengeTimestamp <= CHALLENGE_TIMEOUT,
            "Challenge expired"
        );

        bytes32 messageHash = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            session.challenge
        ));

        address recovered = messageHash.recover(signature);
        require(recovered == msg.sender, "Invalid signature");

        session.state = AuthState.AUTHENTICATED;
        session.relayEnabled = _checkRelayConfig(msg.sender);

        emit NodeAuthenticated(msg.sender);
    }

    function _checkRelayConfig(address node) internal view returns (bool) {
        // Environment-dependent: relay is enabled based on oracle config
        // The relay forwarding flag determines if authenticated nodes can
        // forward cache operations on behalf of other nodes
        return _allowRelayForwarding && trustedRelays[node];
    }

    /**
     * @notice Forward a cache write on behalf of another authenticated node
     * @dev This is the relay mechanism - allows nodes to proxy operations
     * @param targetNode The node whose cache entry is being updated
     * @param key Cache key
     * @param value Cache value
     * @param authProof Signature from the target node authorizing this relay
     */
    function relayCacheWrite(
        address targetNode,
        bytes32 key,
        bytes memory value,
        bytes memory authProof
    ) external {
        NodeSession storage senderSession = sessions[msg.sender];
        require(senderSession.state == AuthState.AUTHENTICATED, "Sender not authenticated");
        require(senderSession.relayEnabled, "Relay not enabled for sender");

        // Verify the target node has an active session
        NodeSession storage targetSession = sessions[targetNode];
        require(targetSession.state == AuthState.AUTHENTICATED, "Target not authenticated");

        // Verify authorization from target - BUT uses sender's challenge as domain
        // This creates a relay vulnerability: the proof is bound to sender's context
        // not the target's, allowing challenge replay across sessions
        bytes32 relayHash = _computeRelayHash(
            senderSession.challenge,  // Uses sender's challenge, not target's
            targetNode,
            key,
            value
        );

        bytes32 signedHash = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            relayHash
        ));

        address proofSigner = signedHash.recover(authProof);
        require(proofSigner == targetNode, "Invalid relay authorization");

        // Write to cache as if from target node
        cache[key] = CacheEntry({
            key: key,
            value: value,
            timestamp: block.timestamp,
            origin: targetNode
        });

        emit CacheUpdated(key, targetNode);
        emit RelayForwarded(msg.sender, targetNode, key);
    }

    function _computeRelayHash(
        bytes32 contextChallenge,
        address target,
        bytes32 key,
        bytes memory value
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(
            _domainSeparator,
            contextChallenge,
            target,
            key,
            keccak256(value)
        ));
    }

    function directCacheWrite(bytes32 key, bytes memory value) external {
        NodeSession storage session = sessions[msg.sender];
        require(session.state == AuthState.AUTHENTICATED, "Not authenticated");

        cache[key] = CacheEntry({
            key: key,
            value: value,
            timestamp: block.timestamp,
            origin: msg.sender
        });

        emit CacheUpdated(key, msg.sender);
    }

    function setTrustedRelay(address relay, bool trusted) external onlyOwner {
        trustedRelays[relay] = trusted;
    }

    function setRelayForwarding(bool enabled) external onlyOwner {
        _allowRelayForwarding = enabled;
    }

    function resetSession(address node) external onlyOwner {
        delete sessions[node];
    }

    function getCacheEntry(bytes32 key) external view returns (
        bytes memory value,
        uint256 timestamp,
        address origin
    ) {
        CacheEntry storage entry = cache[key];
        return (entry.value, entry.timestamp, entry.origin);
    }
}
